(5085589, 740537, 54478, '<td valign="top">Nice. Lighting adds a lot of feel to the photo.</td>', 'Nice. Lighting adds a lot of feel to the photo.', '2008-11-26 11:28:48.000000', NULL, 1),
(5085592, 741324, 54478, '<td valign="top">Nice. Attention is drawn to the cut on the leaf.</td>', 'Nice. Attention is drawn to the cut on the leaf.', '2008-11-26 11:29:32.000000', NULL, 1),
(5085596, 740770, 54478, '<td valign="top">Not sure how I feel about this one. I am not sure it qualifies. If this isn''t a filter, than the distortion from the glass is distracting.</td>', 'Not sure how I feel about this one. I am not sure it qualifies. If this isn''t a filter, than the distortion from the glass is distracting.', '2008-11-26 11:30:41.000000', NULL, 1),
(5085599, 741797, 54478, '<td valign="top">Trees in foreground are distracting. There is also a very slight glow around the buildings. The glow looks like it is caused by the over use of the unsharp mask filter.</td>', 'Trees in foreground are distracting. There is also a very slight glow around the buildings. The glow looks like it is caused by the over use of the unsharp mask filter.', '2008-11-26 11:32:37.000000', NULL, 1),
