(5086287, 742018, 43774, '<td valign="top">I love Queen Anne''s Lace, such a delicate flower and looks beautiful even when dead. Very nice lighting and bokeh here.</td>', 'I love Queen Anne''s Lace, such a delicate flower and looks beautiful even when dead. Very nice lighting and bokeh here.', '2008-11-26 16:25:00.000000', NULL, 1),
(5086288, 740581, 88204, '<td valign="top">The front lighting actually stands out to me more than the backlight. Still a nice shot.</td>', 'The front lighting actually stands out to me more than the backlight. Still a nice shot.', '2008-11-26 16:25:12.000000', NULL, 1),
(5086289, 741957, 43774, '<td valign="top">Stunning!!! This is pretty well perfect to me.</td>', 'Stunning!!! This is pretty well perfect to me.', '2008-11-26 16:25:14.000000', NULL, 1),
(5086290, 740581, 43774, '<td valign="top">Very nice, great colour and I like the glow caused by the lighting. I might have altered the composition just a bit so it wasn''t so centered.</td>', 'Very nice, great colour and I like the glow caused by the lighting. I might have altered the composition just a bit so it wasn''t so centered.', '2008-11-26 16:25:17.000000', NULL, 1),
(5086291, 741993, 43774, '<td valign="top">Oh that''s cool!</td>', 'Oh that''s cool!', '2008-11-26 16:25:29.000000', NULL, 1);
