(5087770, 742044, 35708, '<td valign="top">This is an interesting shot. To be honest the pose drives me nuts simply because it is not a stable shooting stance but then I think a proper stance wouldn''t lead to as interesting of an image. The backlighting is very apparent and yet not over done. Even more interesting it looks as though a shot was fired since the slide is not quite all the way forward... I''ve got to give this one a 9 and hope to see a ribbon on it... just too interesting an image to let die off.</td>', 'This is an interesting shot. To be honest the pose drives me nuts simply because it is not a stable shooting stance but then I think a proper stance wouldn''t lead to as interesting of an image. The backlighting is very apparent and yet not over done. Even more interesting it looks as though a shot was fired since the slide is not quite all the way forward... I''ve got to give this one a 9 and hope to see a ribbon on it... just too interesting an image to let die off.', '2008-11-27 21:56:58.000000', NULL, 1),
(5087771, 741860, 35708, '<td valign="top">A great shot and I am giving it a 7. The backlighting is a little over done around the bottle (mainly the cap area) which I think would be better behind the bottle itself. That would make the eyes drawn more to the middle of the bottle instead of around the cap.</td>', 'A great shot and I am giving it a 7. The backlighting is a little over done around the bottle (mainly the cap area) which I think would be better behind the bottle itself. That would make the eyes drawn more to the middle of the bottle instead of around the cap.', '2008-11-27 21:59:04.000000', NULL, 1),
(5087773, 742022, 35708, '<td valign="top">This is odd and interesting. It doesn''t even look like a photograph. If that is what you were going for then you nailed it. Very crisp and clean... Part of me says rate it lower and part says rate it higher. I am going to go with the rate it higher feeling. Good way to keep me staring at it for awhile. An interesting shot indeed!</td>', 'This is odd and interesting. It doesn''t even look like a photograph. If that is what you were going for then you nailed it. Very crisp and clean... Part of me says rate it lower and part says rate it higher. I am going to go with the rate it higher feeling. Good way to keep me staring at it for awhile. An interesting shot indeed!', '2008-11-27 22:01:01.000000', NULL, 1),
(5087774, 742093, 35708, '<td valign="top">Ok, so this shot isn''t as crisp and clean as some of the other images I rated highly but I really like this one. It almost has that illustrated look that an HDR photo could get. I think this is an interesting shot. With advanced editing rules I think you could have really nailed it with this shot.</td>', 'Ok, so this shot isn''t as crisp and clean as some of the other images I rated highly but I really like this one. It almost has that illustrated look that an HDR photo could get. I think this is an interesting shot. With advanced editing rules I think you could have really nailed it with this shot.', '2008-11-27 22:02:36.000000', NULL, 1),
(5087776, 741685, 35708, '<td valign="top">To be honest, the backlighting is what ruined this shot. The skyline and fence with fill light is amazing. PLEASE tell me you have a shot of this without the backlight! It would be awesome. The backlight is just way to harsh and the spill on the ground is highly distracting. If it were not a backlight challenge and that backlight wasn''t there I would nail this one at a 7 or 8. Regardless, I am giving it a 5 just because you kept me engaged and looking at it for awhile.</td>', 'To be honest, the backlighting is what ruined this shot. The skyline and fence with fill light is amazing. PLEASE tell me you have a shot of this without the backlight! It would be awesome. The backlight is just way to harsh and the spill on the ground is highly distracting. If it were not a backlight challenge and that backlight wasn''t there I would nail this one at a 7 or 8. Regardless, I am giving it a 5 just because you kept me engaged and looking at it for awhile.', '2008-11-27 22:05:09.000000', NULL, 1),
(5087777, 741920, 35708, '<td valign="top">Colors are good, backlighting is a little over done, but the subject is kinda boring. Seen this same thing in other challenges.</td>', 'Colors are good, backlighting is a little over done, but the subject is kinda boring. Seen this same thing in other challenges.', '2008-11-27 22:06:34.000000', NULL, 1),
(5087778, 741933, 35708, '<td valign="top">This is a beautiful photo but it looks more to be side lighting rather than back lighting.</td>', 'This is a beautiful photo but it looks more to be side lighting rather than back lighting.', '2008-11-27 22:08:34.000000', NULL, 1),
(5087779, 740688, 35708, '<td valign="top">Nice shot but the challenge was to keep the subject from becoming a silhouette.</td>', 'Nice shot but the challenge was to keep the subject from becoming a silhouette.', '2008-11-27 22:09:17.000000', NULL, 1),
(5087780, 742005, 35708, '<td valign="top">Ok, got to say that I really do not find anything good or interesting about this photo... except that you took the challenge name totally out of context. I find it hilarious. Nice one.</td>', 'Ok, got to say that I really do not find anything good or interesting about this photo... except that you took the challenge name totally out of context. I find it hilarious. Nice one.', '2008-11-27 22:10:31.000000', NULL, 1),
(5087784, 740803, 35708, '<td valign="top">Back light is way, way, way too overdone. It just really makes this photo bomb.</td>', 'Back light is way, way, way too overdone. It just really makes this photo bomb.', '2008-11-27 22:11:54.000000', NULL, 1),
(5087785, 741971, 35708, '<td valign="top">Challenge was to keep the subject from becoming a silhouette. It didn''t but not by much. Quality of the details is severely lacking as well as any interesting points.</td>', 'Challenge was to keep the subject from becoming a silhouette. It didn''t but not by much. Quality of the details is severely lacking as well as any interesting points.', '2008-11-27 22:12:56.000000', NULL, 1),
(5087786, 741550, 35708, '<td valign="top">The subject isn''t actually back lit here.</td>', 'The subject isn''t actually back lit here.', '2008-11-27 22:13:58.000000', NULL, 1),
(5087788, 741963, 35708, '<td valign="top">I initially rated this one really low but in hindsight I am bumping it up a bit. The first reaction was due to the subject very close to being a silhouette (challenge rules). But it is a great shot and I cannot bring myself to tag it so low. Just wanted to give you my thoughts as many other votes may have rated it low for that reason.</td>', 'I initially rated this one really low but in hindsight I am bumping it up a bit. The first reaction was due to the subject very close to being a silhouette (challenge rules). But it is a great shot and I cannot bring myself to tag it so low. Just wanted to give you my thoughts as many other votes may have rated it low for that reason.', '2008-11-27 22:18:37.000000', NULL, 1),
(5087841, 741982, 98171, '<td valign="top">beautiful portrait....I gave it a 10. Love the B&amp;W, and of course, who could go wrong with a cute baby?</td>', 'beautiful portrait....I gave it a 10. Love the B&W, and of course, who could go wrong with a cute baby?', '2008-11-27 23:17:37.000000', NULL, 1),
(5087843, 741998, 98171, '<td valign="top">I just love this image. Everything is right about it. It sticks out to me from the 30 or so other flower images entered in the challenge. This is the only flower image that I gave a 10. The lighting, background, and subject are all flawless.</td>', 'I just love this image. Everything is right about it. It sticks out to me from the 30 or so other flower images entered in the challenge. This is the only flower image that I gave a 10. The lighting, background, and subject are all flawless.', '2008-11-27 23:18:31.000000', NULL, 1),
(5087846, 740454, 98171, '<td valign="top">I just think this is a gorgeous portrait...I love how she is looking the other way and it''s almost like the image is not focused on her, but yet it is. I gave this a 10.</td>', 'I just think this is a gorgeous portrait...I love how she is looking the other way and it''s almost like the image is not focused on her, but yet it is. I gave this a 10.', '2008-11-27 23:19:30.000000', NULL, 1),
(5087847, 740478, 98171, '<td valign="top">gorgeous portrait, I love it. The model is pretty as well, that helps =) Definitely worth a 10.</td>', 'gorgeous portrait, I love it. The model is pretty as well, that helps =) Definitely worth a 10.', '2008-11-27 23:19:56.000000', NULL, 1),
(5087848, 742031, 98171, '<td valign="top">wow, this is a very nice picture. I am personally a big fan of great food pics, so I may be biased, but this is a great photo. Lighting and setup is perfect. I give this a 9.</td>', 'wow, this is a very nice picture. I am personally a big fan of great food pics, so I may be biased, but this is a great photo. Lighting and setup is perfect. I give this a 9.', '2008-11-27 23:20:37.000000', NULL, 1),
(5087854, 742029, 98171, '<td valign="top">I like this a lot. I like the fact that you added interest to the picture by using the tribal markings.</td>', 'I like this a lot. I like the fact that you added interest to the picture by using the tribal markings.', '2008-11-27 23:26:19.000000', NULL, 1),
(5087867, 741682, 108248, '<td valign="top">I actually like this picture, however, I feel that the bridge distracts from the main focus of the picture, which I am taking to be the lighthouse. If I were taking this photo, I might have zoomed in on the lighthouse more.<br/> <br/>6</td>', 'I actually like this picture, however, I feel that the bridge distracts from the main focus of the picture, which I am taking to be the lighthouse. If I were taking this photo, I might have zoomed in on the lighthouse more. 6', '2008-11-27 23:34:40.000000', NULL, 1),
(5087870, 741994, 108248, '<td valign="top">To me the picture just seems cluttered and waaay to centered, but it does fit the challenge. The edges also seem somewhat out of focus.<br/> <br/>5</td>', 'To me the picture just seems cluttered and waaay to centered, but it does fit the challenge. The edges also seem somewhat out of focus. 5', '2008-11-27 23:36:22.000000', NULL, 1),
(5087872, 742085, 108248, '<td valign="top">I like the reflection although I am not sure if this violates the no drinking glasses clause in the rules. Also, for me the picture really doesn''t have that much meaning for me.<br/> <br/>4</td>', 'I like the reflection although I am not sure if this violates the no drinking glasses clause in the rules. Also, for me the picture really doesn''t have that much meaning for me. 4', '2008-11-27 23:38:17.000000', NULL, 1),
(5087876, 741917, 108248, '<td valign="top">Wow, there are a lot of flower pictures in this challenge. I really like how the petals are illuminated but the center and some of the petals have sort of become a silhouette, which kind of violates the rule. I would have zoomed out and illuminated the whole flower to show its true beauty.<br/> <br/>5</td>', 'Wow, there are a lot of flower pictures in this challenge. I really like how the petals are illuminated but the center and some of the petals have sort of become a silhouette, which kind of violates the rule. I would have zoomed out and illuminated the whole flower to show its true beauty. 5', '2008-11-27 23:42:44.000000', NULL, 1),
(5087879, 741956, 108248, '<td valign="top">All I can say is that it is horribly out of focus and the lighting is horrible.</td>', 'All I can say is that it is horribly out of focus and the lighting is horrible.', '2008-11-27 23:43:58.000000', NULL, 1),
(5087891, 741081, 108248, '<td valign="top">It seems kind of cluttered. I would have focused on a couple of leaves. Nevertheless it fits the challenge. <br/> <br/>5</td>', 'It seems kind of cluttered. I would have focused on a couple of leaves. Nevertheless it fits the challenge.  5', '2008-11-27 23:51:22.000000', NULL, 1),
(5087894, 740478, 108248, '<td valign="top">Very nice outdoor portrait and I love the use of the sun as a natural source of light.<br/> <br/>6</td>', 'Very nice outdoor portrait and I love the use of the sun as a natural source of light. 6', '2008-11-27 23:52:37.000000', NULL, 1),
(5087895, 741387, 108248, '<td valign="top">I think color might have worked better here and maybe a lot more light to really illumate her, not just her hair.<br/> <br/>5</td>', 'I think color might have worked better here and maybe a lot more light to really illumate her, not just her hair. 5', '2008-11-27 23:54:06.000000', NULL, 1),
(5087896, 740439, 108248, '<td valign="top">I don''t really see what you were going for here.<br/> <br/>4</td>', 'I don''t really see what you were going for here. 4', '2008-11-27 23:55:04.000000', NULL, 1),
(5087897, 740780, 108248, '<td valign="top">Great idea for the use of backlighting but it might have been good to fill it with fruit and turn it around.<br/> <br/>5</td>', 'Great idea for the use of backlighting but it might have been good to fill it with fruit and turn it around. 5', '2008-11-27 23:56:22.000000', NULL, 1),
(5087898, 741997, 63633, '<td valign="top">Is that real? Freaky nonetheless! Lovely composition too - one of my favourites so far.</td>', 'Is that real? Freaky nonetheless! Lovely composition too - one of my favourites so far.', '2008-11-27 23:56:40.000000', NULL, 1),
(5087899, 740756, 108248, '<td valign="top">It seems to me that you ended up having almost a complete silhouette, which violates the rules. The only leaf that is completely illuminated seems out of focus.<br/> <br/>3</td>', 'It seems to me that you ended up having almost a complete silhouette, which violates the rules. The only leaf that is completely illuminated seems out of focus. 3', '2008-11-27 23:57:37.000000', NULL, 1),
(5087900, 741854, 63633, '<td valign="top">This has such a lovely feel to it. I love your processing - hope you will share post-challenge.</td>', 'This has such a lovely feel to it. I love your processing - hope you will share post-challenge.', '2008-11-27 23:57:50.000000', NULL, 1),
(5087902, 742133, 108248, '<td valign="top">I don''t really get the whole using woodies in pictures thing, but I like the idea and you did use backlighting.<br/> <br/>6</td>', 'I don''t really get the whole using woodies in pictures thing, but I like the idea and you did use backlighting. 6', '2008-11-27 23:58:27.000000', NULL, 1),
(5087906, 741957, 108248, '<td valign="top">This what I suggested someone else do that had a mess of red leaves, I would have liked a closeup so that you could really see the veins in the leaf, and since its symmetric, I would have rotated it and taken the picutre straight up and down to show the beauty of the symmetry.</td>', 'This what I suggested someone else do that had a mess of red leaves, I would have liked a closeup so that you could really see the veins in the leaf, and since its symmetric, I would have rotated it and taken the picutre straight up and down to show the beauty of the symmetry.', '2008-11-28 00:00:03.000000', NULL, 1),
(5087907, 742146, 108248, '<td valign="top">Why does the flower on the right seem completely white while the others are yellow, kind of out of place, maybe put that one in the middle, but good use of lighting.<br/> <br/>5</td>', 'Why does the flower on the right seem completely white while the others are yellow, kind of out of place, maybe put that one in the middle, but good use of lighting. 5', '2008-11-28 00:01:27.000000', NULL, 1),
(5087910, 742097, 108248, '<td valign="top">I think the black and white really takes away from you photo, but I guess its all about perspective. It seems like this is frontlit, not backlit, but....<br/> <br/>5</td>', 'I think the black and white really takes away from you photo, but I guess its all about perspective. It seems like this is frontlit, not backlit, but.... 5', '2008-11-28 00:02:56.000000', NULL, 1),
(5087912, 740550, 63633, '<td valign="top">Weird and spooky! :)</td>', 'Weird and spooky! :)', '2008-11-28 00:03:39.000000', NULL, 1),
(5087914, 741993, 108248, '<td valign="top">I like this, took me a bit to realize you had a ropelight under the skeleton, but...I just wish the light were brighter...]<br/> <br/>6</td>', 'I like this, took me a bit to realize you had a ropelight under the skeleton, but...I just wish the light were brighter...] 6', '2008-11-28 00:04:09.000000', NULL, 1),
(5087918, 741982, 108248, '<td valign="top">It is a good use of backlighting and the picture is great, but I would have liked the light to be almost right behind the baby''s head to create that halo effect. Nevertheless, great pic<br/> <br/>8</td>', 'It is a good use of backlighting and the picture is great, but I would have liked the light to be almost right behind the baby''s head to create that halo effect. Nevertheless, great pic 8', '2008-11-28 00:06:56.000000', NULL, 1),
(5087921, 741047, 63633, '<td valign="top">hmm... Isn''t that the second one of these I''ve seen? Not sure about the objects on the outside- they don''t seem to add much to the image, and they have forced you to make the central part quite small in order to meet the image size requirements. I would have cropped more tightly and left them out, but just my opinion of course.</td>', 'hmm... Isn''t that the second one of these I''ve seen? Not sure about the objects on the outside- they don''t seem to add much to the image, and they have forced you to make the central part quite small in order to meet the image size requirements. I would have cropped more tightly and left them out, but just my opinion of course.', '2008-11-28 00:07:43.000000', NULL, 1),
(5087922, 741577, 108248, '<td valign="top">Great depth of field control, but when using the sun as a backlight, I feel that the subject should be much brighter, maybe taking it from a different angle.<br/> <br/>6</td>', 'Great depth of field control, but when using the sun as a backlight, I feel that the subject should be much brighter, maybe taking it from a different angle. 6', '2008-11-28 00:08:06.000000', NULL, 1),
(5087925, 741829, 63633, '<td valign="top">I love what you''ve done here. Looks like Christmas decorations :) Very unusual take on a subject that has been done to death in this challenge :)</td>', 'I love what you''ve done here. Looks like Christmas decorations :) Very unusual take on a subject that has been done to death in this challenge :)', '2008-11-28 00:08:40.000000', NULL, 1),
(5087927, 741473, 108248, '<td valign="top">Is this a monument or a picture........personally I don''t like pictures of stuff like this because its not "original", but you did use backlighting.<br/> <br/>4</td>', 'Is this a monument or a picture........personally I don''t like pictures of stuff like this because its not "original", but you did use backlighting. 4', '2008-11-28 00:11:19.000000', NULL, 1),
(5087928, 742113, 63633, '<td valign="top">Oh, I''m in so many minds about this one. Firstly, I really like this - the colours, the composition - everything. The problem is that although they are vases (I think) I think it still breaks the spirit of the rule that says you are not to use drinking glasses in your entry. Just my opinion, and I have been consistent with my voting on all the other ''almost drinking glasses'' entries.<br/> <br/>6 nonetheless, but would have been higher.</td>', 'Oh, I''m in so many minds about this one. Firstly, I really like this - the colours, the composition - everything. The problem is that although they are vases (I think) I think it still breaks the spirit of the rule that says you are not to use drinking glasses in your entry. Just my opinion, and I have been consistent with my voting on all the other ''almost drinking glasses'' entries. 6 nonetheless, but would have been higher.', '2008-11-28 00:11:52.000000', NULL, 1),
(5087929, 740779, 108248, '<td valign="top">I wish the petals were not covering the pretty green center, but other than that, I like.<br/> <br/>7</td>', 'I wish the petals were not covering the pretty green center, but other than that, I like. 7', '2008-11-28 00:12:35.000000', NULL, 1),
(5087931, 741918, 63633, '<td valign="top">You''ve lit this wonderfully. I''d love to see your setup one the challenge is over.</td>', 'You''ve lit this wonderfully. I''d love to see your setup one the challenge is over.', '2008-11-28 00:13:00.000000', NULL, 1),
(5087932, 742009, 108248, '<td valign="top">Not enough light and you can''t really tell what it is or what you are trying to accomplish with the picture.</td>', 'Not enough light and you can''t really tell what it is or what you are trying to accomplish with the picture.', '2008-11-28 00:13:17.000000', NULL, 1),
(5087941, 740454, 108248, '<td valign="top">I like the idea, but the full on sun is a bit much although you probably couldn''t get away from that without violating the whole silhouette thing, so...<br/> <br/>7</td>', 'I like the idea, but the full on sun is a bit much although you probably couldn''t get away from that without violating the whole silhouette thing, so... 7', '2008-11-28 00:15:52.000000', NULL, 1),
(5087943, 741712, 108248, '<td valign="top">I love that you took this picture straight on like this but I wouldn''t have zoomed in as much and a little more light wouldn''t hurt.<br/> <br/>6</td>', 'I love that you took this picture straight on like this but I wouldn''t have zoomed in as much and a little more light wouldn''t hurt. 6', '2008-11-28 00:16:40.000000', NULL, 1),
(5087950, 741831, 108248, '<td valign="top">Although the skyline might be beautiful, I just really think this picture is lacking as far as the use of backlight, so</td>', 'Although the skyline might be beautiful, I just really think this picture is lacking as far as the use of backlight, so', '2008-11-28 00:19:26.000000', NULL, 1),
(5087952, 741254, 108248, '<td valign="top">The use of lighting here was great, but I just really am not digging the orientation of the cactus/flower<br/> <br/>5</td>', 'The use of lighting here was great, but I just really am not digging the orientation of the cactus/flower 5', '2008-11-28 00:21:07.000000', NULL, 1),
(5087954, 741987, 108248, '<td valign="top">More light....the picture is light on the left and fades as you move to the right...maybe centering the light would be better but I love the symmetry<br/> <br/>6</td>', 'More light....the picture is light on the left and fades as you move to the right...maybe centering the light would be better but I love the symmetry 6', '2008-11-28 00:22:22.000000', NULL, 1),
(5087955, 742044, 108248, '<td valign="top">Seems like a weird subject for this challenge although you have used backlighting well.<br/> <br/>5</td>', 'Seems like a weird subject for this challenge although you have used backlighting well. 5', '2008-11-28 00:23:21.000000', NULL, 1),
(5087958, 740470, 108248, '<td valign="top">wow this actually does look like a mitten. It might have been a good idea to get closer and take it from a different angle.<br/> <br/>5</td>', 'wow this actually does look like a mitten. It might have been a good idea to get closer and take it from a different angle. 5', '2008-11-28 00:24:55.000000', NULL, 1),
(5087969, 742018, 108248, '<td valign="top">Seems sort of bland but you did use the sun as a backlight.<br/> <br/>3</td>', 'Seems sort of bland but you did use the sun as a backlight. 3', '2008-11-28 00:29:29.000000', NULL, 1),
(5087972, 741455, 108248, '<td valign="top">the little fibers around the main subject in your photo are kind of distracting. Great use of backlighting though.<br/> <br/>5</td>', 'the little fibers around the main subject in your photo are kind of distracting. Great use of backlighting though. 5', '2008-11-28 00:30:58.000000', NULL, 1),
(5087995, 742128, 63633, '<td valign="top">I don''t think that this shot is going to get the credit it deserves. I know it is very difficult to freeze a butterfly in flight, particularly with such strong composition and beautiful tones. It s even backlit to boot! A very rare 10 from me.</td>', 'I don''t think that this shot is going to get the credit it deserves. I know it is very difficult to freeze a butterfly in flight, particularly with such strong composition and beautiful tones. It s even backlit to boot! A very rare 10 from me.', '2008-11-28 00:42:29.000000', NULL, 1),
(5087996, 741899, 63633, '<td valign="top">If this isn''t Irene''s, then they''ve cloned her. Exceptionally executed as usual :)</td>', 'If this isn''t Irene''s, then they''ve cloned her. Exceptionally executed as usual :)', '2008-11-28 00:43:26.000000', NULL, 1),
(5087998, 740913, 63633, '<td valign="top">Lovely. Would sell well as a stock photo. Your spelling is atrocious though :)</td>', 'Lovely. Would sell well as a stock photo. Your spelling is atrocious though :)', '2008-11-28 00:46:16.000000', NULL, 1),
(5088008, 742141, 63633, '<td valign="top">I like your image, but this is a silhouette, and the challenge description forbids that.</td>', 'I like your image, but this is a silhouette, and the challenge description forbids that.', '2008-11-28 00:53:28.000000', NULL, 1),
(5088010, 741927, 63633, '<td valign="top">Wow. Lovely. Composition is wonderful and the tones beautiful.</td>', 'Wow. Lovely. Composition is wonderful and the tones beautiful.', '2008-11-28 00:54:42.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5088067, 742100, 39825, '<td valign="top">hairy. :-) but looks cool in this case.</td>', 'hairy. :-) but looks cool in this case.', '2008-11-28 02:12:15.000000', NULL, 1),
(5088086, 742144, 49109, '<td valign="top">too much filtering/processing for my taste. i can''t even guess what this is -the puzzle macro challenge was last week. the green bar at top gives an interesting touch, though</td>', 'too much filtering/processing for my taste. i can''t even guess what this is -the puzzle macro challenge was last week. the green bar at top gives an interesting touch, though', '2008-11-28 03:26:35.000000', NULL, 1),
(5088088, 740441, 49109, '<td valign="top">good capture, but to me this is not real backlighting, most of the light comes from above</td>', 'good capture, but to me this is not real backlighting, most of the light comes from above', '2008-11-28 03:27:59.000000', NULL, 1),
(5088090, 742031, 49109, '<td valign="top">the soft shadows tell that this is not backlighting. composition is a bit lame, too. nice DOF.</td>', 'the soft shadows tell that this is not backlighting. composition is a bit lame, too. nice DOF.', '2008-11-28 03:29:13.000000', NULL, 1),
(5088091, 741581, 49109, '<td valign="top">nice idea, well executed except for the greyish background, wish it was brighter</td>', 'nice idea, well executed except for the greyish background, wish it was brighter', '2008-11-28 03:31:36.000000', NULL, 1),
