(5089521, 741224, 97225, '<td valign="top">Nice composition and atmosphere. 9</td>', 'Nice composition and atmosphere. 9', '2008-11-29 00:33:19.000000', NULL, 1),
(5089524, 742096, 97225, '<td valign="top">Nice composition and colour.</td>', 'Nice composition and colour.', '2008-11-29 00:34:01.000000', NULL, 1),
(5089529, 741047, 97225, '<td valign="top">??? Didn''t I see this already?</td>', '??? Didn''t I see this already?', '2008-11-29 00:35:23.000000', NULL, 1),
(5089533, 742138, 97225, '<td valign="top">Beautiful flower shot. I love the glowing orange against the black. 9</td>', 'Beautiful flower shot. I love the glowing orange against the black. 9', '2008-11-29 00:36:33.000000', NULL, 1),
(5089537, 741796, 97225, '<td valign="top">The colours are gorgeous.</td>', 'The colours are gorgeous.', '2008-11-29 00:37:16.000000', NULL, 1),
(5089540, 742100, 97225, '<td valign="top">That is beautiful the way the hairiness stands out against the dark background. 9</td>', 'That is beautiful the way the hairiness stands out against the dark background. 9', '2008-11-29 00:38:33.000000', NULL, 1),
(5089543, 741905, 97225, '<td valign="top">I absolutely love the colours in this. 10</td>', 'I absolutely love the colours in this. 10', '2008-11-29 00:39:29.000000', NULL, 1),
(5089546, 741990, 97225, '<td valign="top">I think that this would be stunning with sharper focus.</td>', 'I think that this would be stunning with sharper focus.', '2008-11-29 00:40:24.000000', NULL, 1),
(5089549, 741995, 97225, '<td valign="top">This doesn''t actually look like the light is behind it to me.</td>', 'This doesn''t actually look like the light is behind it to me.', '2008-11-29 00:41:49.000000', NULL, 1),
(5089551, 741645, 97225, '<td valign="top">Beautiful flower study. There are a few along these lines and I love most of them. 9</td>', 'Beautiful flower study. There are a few along these lines and I love most of them. 9', '2008-11-29 00:42:35.000000', NULL, 1),
(5089554, 741387, 97225, '<td valign="top">Absolutely gorgeous portrait.</td>', 'Absolutely gorgeous portrait.', '2008-11-29 00:44:18.000000', NULL, 1),
(5089557, 741821, 97225, '<td valign="top">Lovely portrait but the backlighting has been well and truly upstaged.</td>', 'Lovely portrait but the backlighting has been well and truly upstaged.', '2008-11-29 00:45:47.000000', NULL, 1),
(5089563, 742060, 97225, '<td valign="top">Beautiful horse nicely focused and the light is good but I find the crop a bit uncomfortable.</td>', 'Beautiful horse nicely focused and the light is good but I find the crop a bit uncomfortable.', '2008-11-29 00:47:23.000000', NULL, 1),
(5089566, 742092, 97225, '<td valign="top">Lovely shot.</td>', 'Lovely shot.', '2008-11-29 00:48:29.000000', NULL, 1),
(5089568, 741857, 97225, '<td valign="top">Beautiful shot.</td>', 'Beautiful shot.', '2008-11-29 00:48:50.000000', NULL, 1),
(5089572, 741342, 97225, '<td valign="top">Beautiful shot. I love the lit up beak.</td>', 'Beautiful shot. I love the lit up beak.', '2008-11-29 00:50:15.000000', NULL, 1),
(5089577, 741927, 97225, '<td valign="top">Lovely shot. Nice colour, composition and beautiful light.</td>', 'Lovely shot. Nice colour, composition and beautiful light.', '2008-11-29 00:51:36.000000', NULL, 1),
(5089579, 742054, 97225, '<td valign="top">Lovely sunburst.</td>', 'Lovely sunburst.', '2008-11-29 00:52:14.000000', NULL, 1),
(5089584, 741455, 97225, '<td valign="top">Beautiful and delicate.</td>', 'Beautiful and delicate.', '2008-11-29 00:53:32.000000', NULL, 1),
(5089585, 741548, 97225, '<td valign="top">That is definitely a silhouette.</td>', 'That is definitely a silhouette.', '2008-11-29 00:54:08.000000', NULL, 1),
(5089589, 741099, 97225, '<td valign="top">Lovely shot.</td>', 'Lovely shot.', '2008-11-29 00:54:50.000000', NULL, 1),
(5089590, 741982, 97225, '<td valign="top">How adorable!</td>', 'How adorable!', '2008-11-29 00:55:54.000000', NULL, 1),
(5089592, 742077, 97225, '<td valign="top">Beautiful colours.</td>', 'Beautiful colours.', '2008-11-29 00:56:20.000000', NULL, 1),
(5089597, 741722, 97225, '<td valign="top">Lovely catch of light.</td>', 'Lovely catch of light.', '2008-11-29 00:57:23.000000', NULL, 1),
(5089625, 741615, 97225, '<td valign="top">Great image. That is pretty funky lighting.</td>', 'Great image. That is pretty funky lighting.', '2008-11-29 01:10:54.000000', NULL, 1),
(5089626, 741957, 97225, '<td valign="top">That is an absolutely perfect leaf. I love the colour annd the diagonal placement. 9</td>', 'That is an absolutely perfect leaf. I love the colour annd the diagonal placement. 9', '2008-11-29 01:12:16.000000', NULL, 1),
(5089628, 740813, 97225, '<td valign="top">Haha that is neat.</td>', 'Haha that is neat.', '2008-11-29 01:12:58.000000', NULL, 1),
(5089629, 741428, 97225, '<td valign="top">Lovely shot.</td>', 'Lovely shot.', '2008-11-29 01:13:30.000000', NULL, 1),
(5089632, 740441, 97225, '<td valign="top">The image is great but the lighting does not seem to be coming from behind. Maybe it has been killed with fill flash.</td>', 'The image is great but the lighting does not seem to be coming from behind. Maybe it has been killed with fill flash.', '2008-11-29 01:15:34.000000', NULL, 1),
(5089771, 741854, 86628, '<td valign="top">Perfect!</td>', 'Perfect!', '2008-11-29 03:38:13.000000', NULL, 1),
(5089853, 741982, 28322, '<td valign="top">Wonderful .. 10 from me.</td>', 'Wonderful .. 10 from me.', '2008-11-29 07:34:47.000000', NULL, 1),
(5089856, 741993, 28322, '<td valign="top">Thats wonderful .. 10 from me</td>', 'Thats wonderful .. 10 from me', '2008-11-29 07:36:00.000000', NULL, 1),
(5089859, 741963, 28322, '<td valign="top">Niceeeeeeeeeeeeeeeeeee .. 10 from me</td>', 'Niceeeeeeeeeeeeeeeeeee .. 10 from me', '2008-11-29 07:39:59.000000', NULL, 1),
(5089862, 742049, 28322, '<td valign="top">10 from Montreal :)</td>', '10 from Montreal :)', '2008-11-29 07:41:21.000000', NULL, 1),
(5089864, 740731, 28322, '<td valign="top">Thats simply wonderful 10 from me.</td>', 'Thats simply wonderful 10 from me.', '2008-11-29 07:41:47.000000', NULL, 1),
(5089865, 741393, 28322, '<td valign="top">thats simply wonderful .. 10 from me</td>', 'thats simply wonderful .. 10 from me', '2008-11-29 07:42:18.000000', NULL, 1),
(5089866, 742044, 28322, '<td valign="top">very nice composition, I see a tatto on the far arm, I would''ve loved that to be the one closer to the camera, just to adde some gangster feeling .. but it doesn''t mean its a fault, still gets 10 from me :)</td>', 'very nice composition, I see a tatto on the far arm, I would''ve loved that to be the one closer to the camera, just to adde some gangster feeling .. but it doesn''t mean its a fault, still gets 10 from me :)', '2008-11-29 07:43:34.000000', NULL, 1),
(5089868, 742143, 28322, '<td valign="top">Simple yet nice .. 7</td>', 'Simple yet nice .. 7', '2008-11-29 07:44:12.000000', NULL, 1),
(5089875, 741854, 73250, '<td valign="top">This is my absolute favorite from this challenge. The moment was captured and composed perfectly. Well done.</td>', 'This is my absolute favorite from this challenge. The moment was captured and composed perfectly. Well done.', '2008-11-29 07:48:55.000000', NULL, 1),
(5089876, 741857, 73250, '<td valign="top">This is very well executed. The colors and composition make it for me.</td>', 'This is very well executed. The colors and composition make it for me.', '2008-11-29 07:49:29.000000', NULL, 1),
(5089877, 740791, 73250, '<td valign="top">Very nice perspective and feeling of this image...very ominous!</td>', 'Very nice perspective and feeling of this image...very ominous!', '2008-11-29 07:50:12.000000', NULL, 1),
(5089984, 741899, 81657, '<td valign="top">Really amazing. Love the sharpness and the colours. I''d really like to be able to shoot pictures like this one....</td>', 'Really amazing. Love the sharpness and the colours. I''d really like to be able to shoot pictures like this one....', '2008-11-29 09:33:41.000000', NULL, 1),
(5090022, 741971, 29513, '<td valign="top">Nice, introspective expression and you have the back lighting technique right on.  I would like to see a little more light on the left side of the model''s face, though. 5</td>', 'Nice, introspective expression and you have the back lighting technique right on.  I would like to see a little more light on the left side of the model''s face, though. 5', '2008-11-29 10:20:08.000000', NULL, 1),
(5090024, 741837, 29513, '<td valign="top">Good exposure and I like the water droplets.  I might try a little spot lighting on the buds and on the shadowed part of the leaf at the left plus a bit more contrast.  6</td>', 'Good exposure and I like the water droplets.  I might try a little spot lighting on the buds and on the shadowed part of the leaf at the left plus a bit more contrast.  6', '2008-11-29 10:22:25.000000', NULL, 1),
(5090025, 741912, 29513, '<td valign="top">I like this a lot.  Makes me want to get out the pencils and try my hand at a sketch.  I really like the overlapping vases.  I don''t see much I would change; maybe play with the cropping a bit. 8</td>', 'I like this a lot.  Makes me want to get out the pencils and try my hand at a sketch.  I really like the overlapping vases.  I don''t see much I would change; maybe play with the cropping a bit. 8', '2008-11-29 10:25:29.000000', NULL, 1),
(5090028, 740665, 29513, '<td valign="top">Nice fresh take on back lighting a sphere.  This could be used in a physics book.  If I were going to change something I think I would see what a more landscape crop might look like.  the expanse of light area at the bottom and black area at the top don''t seem add much.  7</td>', 'Nice fresh take on back lighting a sphere.  This could be used in a physics book.  If I were going to change something I think I would see what a more landscape crop might look like.  the expanse of light area at the bottom and black area at the top don''t seem add much.  7', '2008-11-29 10:29:02.000000', NULL, 1),
(5090029, 741997, 29513, '<td valign="top">Nicely done.  I don''t see a thing I would change.  10</td>', 'Nicely done.  I don''t see a thing I would change.  10', '2008-11-29 10:30:50.000000', NULL, 1),
(5090030, 742128, 29513, '<td valign="top">This just goes to show how important a title can be.  I admit to being a bit put off until I read the title.  Very nice.  7</td>', 'This just goes to show how important a title can be.  I admit to being a bit put off until I read the title.  Very nice.  7', '2008-11-29 10:32:59.000000', NULL, 1),
(5090033, 741114, 29513, '<td valign="top">Nice use of back lighting.  Just as a personal preference, I like to see the depth of field deep enough to make every thing lighted as a featured element (the far side of the face and whiskers, for example) be in sharp focus.  So, even taking my bias into account, this is a 7, easy.</td>', 'Nice use of back lighting.  Just as a personal preference, I like to see the depth of field deep enough to make every thing lighted as a featured element (the far side of the face and whiskers, for example) be in sharp focus.  So, even taking my bias into account, this is a 7, easy.', '2008-11-29 10:36:32.000000', NULL, 1),
(5090035, 741393, 29513, '<td valign="top">Nice colors.  This just doesn''t give me anything to hook my attention on, though.  5</td>', 'Nice colors.  This just doesn''t give me anything to hook my attention on, though.  5', '2008-11-29 10:38:24.000000', NULL, 1),
(5090036, 741099, 29513, '<td valign="top">Nice grouping.  I like the lighting but the whole effect is a little to dark for my taste.  Good depth of filed.  Maybe if you cropped it off center? 5</td>', 'Nice grouping.  I like the lighting but the whole effect is a little to dark for my taste.  Good depth of filed.  Maybe if you cropped it off center? 5', '2008-11-29 10:40:49.000000', NULL, 1),
(5090038, 740803, 29513, '<td valign="top">I like this.  I like that the model is off center and that you lit her well enough to get a good exposure and still made a statement with the back light.  I like the intense expression, too.  7</td>', 'I like this.  I like that the model is off center and that you lit her well enough to get a good exposure and still made a statement with the back light.  I like the intense expression, too.  7', '2008-11-29 10:43:13.000000', NULL, 1),
(5090040, 741729, 29513, '<td valign="top">I like the color choices and the exposure of the flower is just right.  I might have cropped a little closer to the flower.  8</td>', 'I like the color choices and the exposure of the flower is just right.  I might have cropped a little closer to the flower.  8', '2008-11-29 10:44:26.000000', NULL, 1),
(5090044, 742082, 29513, '<td valign="top">Very exotic.  I really like the over all effect.  6</td>', 'Very exotic.  I really like the over all effect.  6', '2008-11-29 10:46:13.000000', NULL, 1),
(5090061, 741578, 29513, '<td valign="top">Nice exposure.  I am struck by the parallel between the limited but attractive view out the window and the view we as humans have of our future and purpose for being here.  It is hard to capture this sort of thing.  Well done, if that was your intent.  If that was not your intent, well, such is the nature of Destiny, isn''t it?  8</td>', 'Nice exposure.  I am struck by the parallel between the limited but attractive view out the window and the view we as humans have of our future and purpose for being here.  It is hard to capture this sort of thing.  Well done, if that was your intent.  If that was not your intent, well, such is the nature of Destiny, isn''t it?  8', '2008-11-29 10:51:43.000000', NULL, 1),
(5090070, 740808, 29513, '<td valign="top">I love the light and shadow.  I don''t see anything I would change.  8</td>', 'I love the light and shadow.  I don''t see anything I would change.  8', '2008-11-29 10:55:04.000000', NULL, 1),
(5090168, 742011, 96915, '<td valign="top">To me, that composition is lacking.  There is too much foreground and not enough subject.  If the symmetry itself is intended to be the composition, it would look better if the shot had been taken from straight on, rather than at an angle from the edge of the floor (the horizon is even but the floor is not).</td>', 'To me, that composition is lacking.  There is too much foreground and not enough subject.  If the symmetry itself is intended to be the composition, it would look better if the shot had been taken from straight on, rather than at an angle from the edge of the floor (the horizon is even but the floor is not).', '2008-11-29 12:18:49.000000', NULL, 1),
(5090170, 742141, 94815, '<td valign="top">Thie time the sharpening halo works to good effect.</td>', 'Thie time the sharpening halo works to good effect.', '2008-11-29 12:19:18.000000', NULL, 1),
(5090173, 740803, 96915, '<td valign="top">This one grew on me.  At first the bright glowing background bothered me, but at a second look, I like it and can appreciate the challenge of preserving detail in her face along with the backlighting.  I also like the blue tint on her hair.</td>', 'This one grew on me.  At first the bright glowing background bothered me, but at a second look, I like it and can appreciate the challenge of preserving detail in her face along with the backlighting.  I also like the blue tint on her hair.', '2008-11-29 12:20:54.000000', NULL, 1),
(5090178, 741852, 96915, '<td valign="top">While this is indeed backlit, there is just not enough here to hold my interest.</td>', 'While this is indeed backlit, there is just not enough here to hold my interest.', '2008-11-29 12:22:18.000000', NULL, 1),
(5090184, 741956, 94815, '<td valign="top">Looks like autofocus was fooled by the intense light; so the main subject is badly blurred. If the camera allows it, try manual focusing.</td>', 'Looks like autofocus was fooled by the intense light; so the main subject is badly blurred. If the camera allows it, try manual focusing.', '2008-11-29 12:24:21.000000', NULL, 1),
(5090187, 742142, 96915, '<td valign="top">Though I appreciate the attempt to make this unique by going with B/W, I don''t think it works for me.  The greys kind of blend in together and causes the focus to appear off, though I don''t believe it really is.</td>', 'Though I appreciate the attempt to make this unique by going with B/W, I don''t think it works for me.  The greys kind of blend in together and causes the focus to appear off, though I don''t believe it really is.', '2008-11-29 12:25:33.000000', NULL, 1),
(5090189, 741338, 94815, '<td valign="top">B&amp;W needs a fuller range of tones for impact. This image could be much improved just by increasing contrast and a bit of darkening.</td>', 'B&W needs a fuller range of tones for impact. This image could be much improved just by increasing contrast and a bit of darkening.', '2008-11-29 12:26:28.000000', NULL, 1),
(5090192, 741286, 96915, '<td valign="top">There''s too much going on here for me.  The branches and trunk do not exactly frame the house so much as cover it.  While I see that there is light coming from behind the house, this image doesn''t really exemplify the theme.</td>', 'There''s too much going on here for me.  The branches and trunk do not exactly frame the house so much as cover it.  While I see that there is light coming from behind the house, this image doesn''t really exemplify the theme.', '2008-11-29 12:27:12.000000', NULL, 1),
(5090193, 741820, 94815, '<td valign="top">Colors are unnaturally intense. Otherwise good idea.</td>', 'Colors are unnaturally intense. Otherwise good idea.', '2008-11-29 12:28:10.000000', NULL, 1),
(5090197, 741623, 96915, '<td valign="top">You''re allowed 640 pixels on the long side, and I suggest using all of the size allowed.  This photo is too small to have much impact.  At this size, there doesn''t seem to be a focal point, though the colors seem nice.</td>', 'You''re allowed 640 pixels on the long side, and I suggest using all of the size allowed.  This photo is too small to have much impact.  At this size, there doesn''t seem to be a focal point, though the colors seem nice.', '2008-11-29 12:28:48.000000', NULL, 1),
(5090198, 742142, 94815, '<td valign="top">Blurry.</td>', 'Blurry.', '2008-11-29 12:28:51.000000', NULL, 1),
(5090201, 740781, 94815, '<td valign="top">A bit too ordinary.</td>', 'A bit too ordinary.', '2008-11-29 12:29:27.000000', NULL, 1),
(5090205, 741854, 94815, '<td valign="top">Too bad the wing on the right indrudes so much. The hand and approaching bird are quite nice.</td>', 'Too bad the wing on the right indrudes so much. The hand and approaching bird are quite nice.', '2008-11-29 12:31:30.000000', NULL, 1),
(5090206, 742036, 96915, '<td valign="top">I''ve already seen too much citrus and drops in this and other challenges, but what kills this one for me is that the drop is out of focus.</td>', 'I''ve already seen too much citrus and drops in this and other challenges, but what kills this one for me is that the drop is out of focus.', '2008-11-29 12:32:29.000000', NULL, 1),
(5090211, 742005, 94815, '<td valign="top">Hehe. Or is it hohoho? Maybe hooha! Needs more skin detail.</td>', 'Hehe. Or is it hohoho? Maybe hooha! Needs more skin detail.', '2008-11-29 12:32:45.000000', NULL, 1),
(5090216, 741209, 96915, '<td valign="top">I think that for this to be effective, the bird needs to be larger in the frame, or not competing so much with the branches behind it.</td>', 'I think that for this to be effective, the bird needs to be larger in the frame, or not competing so much with the branches behind it.', '2008-11-29 12:33:33.000000', NULL, 1),
(5090236, 742024, 94815, '<td valign="top">Too unintentionally spooky. Bad color I think. Shift balance toward yellow and cyan.</td>', 'Too unintentionally spooky. Bad color I think. Shift balance toward yellow and cyan.', '2008-11-29 12:43:07.000000', NULL, 1),
(5090237, 740470, 94815, '<td valign="top">"Back" lighting?</td>', '"Back" lighting?', '2008-11-29 12:43:30.000000', NULL, 1),
(5090240, 741796, 94815, '<td valign="top">Lacks foreground detail so loses context and topicality.</td>', 'Lacks foreground detail so loses context and topicality.', '2008-11-29 12:44:26.000000', NULL, 1),
(5090246, 742091, 94815, '<td valign="top">Double talk - off topic.</td>', 'Double talk - off topic.', '2008-11-29 12:46:03.000000', NULL, 1),
