(5091319, 742033, 29513, '<td valign="top">I like the cropping and the use of leading lines.  Good and sharp and nice exposure.  8.</td>', 'I like the cropping and the use of leading lines.  Good and sharp and nice exposure.  8.', '2008-11-30 12:21:31.000000', NULL, 1),
(5091321, 741047, 29513, '<td valign="top">I like the idea.  I think the orange slices might look more impressive against a darker background.  5</td>', 'I like the idea.  I think the orange slices might look more impressive against a darker background.  5', '2008-11-30 12:25:14.000000', NULL, 1),
(5091326, 741933, 29513, '<td valign="top">I really like the way the light really draws the model.  I like the contrast between the texture of the necklace and the model''s skin.  10.</td>', 'I really like the way the light really draws the model.  I like the contrast between the texture of the necklace and the model''s skin.  10.', '2008-11-30 12:29:00.000000', NULL, 1),
(5091334, 742039, 29513, '<td valign="top">You have found the obvious solution to the question of how much background to include with the back lit flower.  It is almost an example of composition do''s.<br/>Leading lines.  Rule-of-thirds.  Not to mention the exposure and sharpness.  10.</td>', 'You have found the obvious solution to the question of how much background to include with the back lit flower.  It is almost an example of composition do''s.Leading lines.  Rule-of-thirds.  Not to mention the exposure and sharpness.  10.', '2008-11-30 12:33:50.000000', NULL, 1),
(5091337, 741857, 29513, '<td valign="top">Beautiful color. And the bubbles are a nice touch.  To me, the border detracts, though.  6</td>', 'Beautiful color. And the bubbles are a nice touch.  To me, the border detracts, though.  6', '2008-11-30 12:37:15.000000', NULL, 1),
(5091350, 741635, 40386, '<td valign="top">Beautiful, this is the kind of photo I had in mind but my muddy horses and lousy weather didnt make it LOL.  My favorite in this challenge!!!! 10</td>', 'Beautiful, this is the kind of photo I had in mind but my muddy horses and lousy weather didnt make it LOL.  My favorite in this challenge!!!! 10', '2008-11-30 12:44:22.000000', NULL, 1),
(5091353, 742060, 40386, '<td valign="top">This is awesome and appears to be taken of the same as the other horse rearing, I just wish you had been able to get more of the legs and tail in the frame.   Still beautiful 8</td>', 'This is awesome and appears to be taken of the same as the other horse rearing, I just wish you had been able to get more of the legs and tail in the frame.   Still beautiful 8', '2008-11-30 12:46:31.000000', NULL, 1),
