(5100230, 741922, 46778, '<td valign="top">Great job. Go team germany.</td>', 'Great job. Go team germany.', '2008-12-03 00:25:29.000000', NULL, 0),
(5100235, 741854, 63806, '<td valign="top">This is absolutely excellent..  ribbon was well deserved</td>', 'This is absolutely excellent..  ribbon was well deserved', '2008-12-03 00:27:08.000000', NULL, 0),
(5100237, 741899, 67697, '<td valign="top">beautiful shot.  i love how you''ve caught the reflection of some more drops too.  cool looking rising swell also.  Congrats on the ribbon!</td>', 'beautiful shot.  i love how you''ve caught the reflection of some more drops too.  cool looking rising swell also.  Congrats on the ribbon!', '2008-12-03 00:28:10.000000', NULL, 0),
(5100238, 741899, 97270, '<td valign="top">Dont you ever get bored with the droplets??<br/> <br/>J/K:-)<br/> <br/>Love the self reflecting water surfaces.<br/> <br/>Congrats!</td>', 'Dont you ever get bored with the droplets?? J/K:-) Love the self reflecting water surfaces. Congrats!', '2008-12-03 00:28:37.000000', NULL, 0),
(5100247, 741620, 62357, '<td valign="top">nice one Deb.  <br/> <br/>Funny, your comment about the contrast.  I recently received a couple of comments about contrast and from where I was standing couldn''t see anything wrong.  It''s tough sometimes with all the different monitors around.  I actually disagree with your commenter, this is not lacking contrast on my laptop (which is the monitor I would expect to see it lacking as it is quite bright).</td>', 'nice one Deb.   Funny, your comment about the contrast.  I recently received a couple of comments about contrast and from where I was standing couldn''t see anything wrong.  It''s tough sometimes with all the different monitors around.  I actually disagree with your commenter, this is not lacking contrast on my laptop (which is the monitor I would expect to see it lacking as it is quite bright).', '2008-12-03 00:30:47.000000', NULL, 0),
(5100268, 742047, 83845, '<td valign="top">Great photo!<br/> <br/>If the glass were cleaner, it would make a big difference.  <br/> <br/>It deserved better than it got, IMO.<br/> <br/>I hope you stick around.  You''d like it.</td>', 'Great photo! If the glass were cleaner, it would make a big difference.   It deserved better than it got, IMO. I hope you stick around.  You''d like it.', '2008-12-03 00:35:31.000000', NULL, 0),
(5100287, 741899, 52115, '<td valign="top">For you, a ribbon is, just another drop in the bucket!<br/>Nice capture. Is this just plain water?</td>', 'For you, a ribbon is, just another drop in the bucket!Nice capture. Is this just plain water?', '2008-12-03 00:41:08.000000', NULL, 0),
(5100292, 740746, 68504, '<td valign="top">A pleasure to view.</td>', 'A pleasure to view.', '2008-12-03 00:42:30.000000', NULL, 0),
(5100304, 741899, 52549, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by justamistere:</b></div><hr/><i> For you, a ribbon is, just another drop in the bucket!<br/>Nice capture. Is this just plain water? </i></td></tr></table> <br/>If you could see my nervous hitting of the update button every two seconds the whole week you''d know that a ribbon is anything but a drop in the bucket ;-))<br/>Yes, it''s plain tap water.</td>', 'Originally posted by justamistere: For you, a ribbon is, just another drop in the bucket!Nice capture. Is this just plain water?  If you could see my nervous hitting of the update button every two seconds the whole week you''d know that a ribbon is anything but a drop in the bucket ;-))Yes, it''s plain tap water.', '2008-12-03 00:47:16.000000', NULL, 0),
(5100307, 741899, 18450, '<td valign="top">Fabulous shot Irene! Congrats on your well deserved blue (((hugs)))</td>', 'Fabulous shot Irene! Congrats on your well deserved blue (((hugs)))', '2008-12-03 00:48:18.000000', NULL, 0),
(5100314, 741854, 18450, '<td valign="top">Outstanding shot! Well deserved top place!!!</td>', 'Outstanding shot! Well deserved top place!!!', '2008-12-03 00:50:18.000000', NULL, 0),
(5100334, 742082, 52115, '<td valign="top">This has great potential, worth a reshoot on a sunny day for another challenge.</td>', 'This has great potential, worth a reshoot on a sunny day for another challenge.', '2008-12-03 00:59:02.000000', NULL, 0),
(5100336, 741854, 52549, '<td valign="top">This is a most beautiful image, Jon. I also love the backlighting of the tiny hairs on the back of the mans hand. Congrats on your ribbon.</td>', 'This is a most beautiful image, Jon. I also love the backlighting of the tiny hairs on the back of the mans hand. Congrats on your ribbon.', '2008-12-03 01:00:06.000000', NULL, 0),
(5100339, 742039, 52549, '<td valign="top">Gorgeous image. I love the vibrant colors and the composition. Congrats on your ribbon and your new PB, Laurie.</td>', 'Gorgeous image. I love the vibrant colors and the composition. Congrats on your ribbon and your new PB, Laurie.', '2008-12-03 01:01:58.000000', NULL, 0),
(5100355, 741854, 39110, '<td valign="top">I dont get the title but I love the image FAVED</td>', 'I dont get the title but I love the image FAVED', '2008-12-03 01:07:27.000000', NULL, 0),
(5100357, 742097, 68504, '<td valign="top">Very effective combination of reverse light and shapes. And great balance of definition and bokeh.</td>', 'Very effective combination of reverse light and shapes. And great balance of definition and bokeh.', '2008-12-03 01:07:56.000000', NULL, 0),
(5100367, 741998, 68504, '<td valign="top">Very nice use of backlighting.</td>', 'Very nice use of backlighting.', '2008-12-03 01:12:16.000000', NULL, 0),
(5100376, 741854, 19708, '<td valign="top"><img alt="'' . substr(''//www.dpchallenge.com/images/rib1.gif'', strrpos(''//www.dpchallenge.com/images/rib1.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/rib1.gif"/> <br/></td>', ' ', '2008-12-03 01:13:56.000000', NULL, 0),
(5100394, 741620, 68504, '<td valign="top">Knew this was yours from the trees... Very rich photo:  the round upper fountain shape and the lovely fall/spray of water/droplets and the pigeon approaching (at your command) is a composition in itself, though I must say my second thought here was thank goodness these guys actually seem to be taking a bath.....</td>', 'Knew this was yours from the trees... Very rich photo:  the round upper fountain shape and the lovely fall/spray of water/droplets and the pigeon approaching (at your command) is a composition in itself, though I must say my second thought here was thank goodness these guys actually seem to be taking a bath.....', '2008-12-03 01:20:08.000000', NULL, 0),
(5100415, 741933, 11467, '<td valign="top">Congratulations on 13th place.<br/> <br/>It''s amazing how many people mistake this for side lighting.<br/>People! In order to get this sort of picture the light has to be behind the model. It only appears to be from the side as it is just out of the picture.<br/> <br/>A great photo.</td>', 'Congratulations on 13th place. It''s amazing how many people mistake this for side lighting.People! In order to get this sort of picture the light has to be behind the model. It only appears to be from the side as it is just out of the picture. A great photo.', '2008-12-03 01:34:35.000000', NULL, 0),
(5100422, 741820, 68504, '<td valign="top">I find this intriguing.  You have certainly ennobled the tupperware, and its texture and colour flirt nicely with the lime''s.</td>', 'I find this intriguing.  You have certainly ennobled the tupperware, and its texture and colour flirt nicely with the lime''s.', '2008-12-03 01:36:42.000000', NULL, 0),
(5100435, 741620, 11467, '<td valign="top">Hi Deb, congratulations on place 36.<br/>Having the sun in the photo &amp; still being able to see the shadow side of everything is pretty difficult.<br/>Well done.</td>', 'Hi Deb, congratulations on place 36.Having the sun in the photo & still being able to see the shadow side of everything is pretty difficult.Well done.', '2008-12-03 01:41:15.000000', NULL, 0),
(5100436, 741902, 68504, '<td valign="top">Very pleasing composition, and the lighting is perfect, with the light edges of the alstroemeria almost but not quite disappearing against the background.</td>', 'Very pleasing composition, and the lighting is perfect, with the light edges of the alstroemeria almost but not quite disappearing against the background.', '2008-12-03 01:41:24.000000', NULL, 0),
(5100439, 741900, 68504, '<td valign="top">What aKiwi said.</td>', 'What aKiwi said.', '2008-12-03 01:42:26.000000', NULL, 0),
(5100440, 742077, 68504, '<td valign="top">I like the action of the leaves all bunched/curled fore and aft, and how the light shows this.  Only criticism is the two darkest areas don''t quite balance either with each other or within the composition.</td>', 'I like the action of the leaves all bunched/curled fore and aft, and how the light shows this.  Only criticism is the two darkest areas don''t quite balance either with each other or within the composition.', '2008-12-03 01:48:13.000000', NULL, 0),
(5100442, 741645, 68504, '<td valign="top">I like this, and the subtlety of the hairs.</td>', 'I like this, and the subtlety of the hairs.', '2008-12-03 01:50:49.000000', NULL, 0),
(5100443, 741394, 68504, '<td valign="top">Love the veins and texture brought out in this - especially endearing is the northeast petal beginning to crumple.</td>', 'Love the veins and texture brought out in this - especially endearing is the northeast petal beginning to crumple.', '2008-12-03 01:55:22.000000', NULL, 0),
(5100446, 741581, 68504, '<td valign="top">Delightful playfulness. Had to linger awhile sorting out the bee components. (Kumquat, grape slices and skin?)</td>', 'Delightful playfulness. Had to linger awhile sorting out the bee components. (Kumquat, grape slices and skin?)', '2008-12-03 02:01:11.000000', NULL, 0),
(5100451, 742128, 68504, '<td valign="top">Like this.  (Let me know when you do Daedalus).</td>', 'Like this.  (Let me know when you do Daedalus).', '2008-12-03 02:08:25.000000', NULL, 0);
